const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').split('\n');
let idx = 0;
const first = data[idx++].trim().split(/\s+/).map(Number);
const N = first[0], M = first[1];
const adj = new Array(N).fill(0);
for (let i = 0; i < M; i++) {
  const line = data[idx++];
  if (!line || line.trim() === '') { i--; continue; }
  const [x, y] = line.trim().split(/\s+/).map(Number);
  adj[x - 1] |= 1 << (y - 1);
  adj[y - 1] |= 1 << (x - 1);
}

const total = 1 << N;
const dp = new Array(total).fill(0);
dp[0] = 1;
for (let mask = 1; mask < total; mask++) {
  const v = mask & -mask;
  const vi = Math.log2(v) | 0;
  // caso 1: v não está no sanduíche
  const without = mask ^ v;
  // caso 2: v está no sanduíche -> vizinhos removidos
  const withoutNb = mask & ~(adj[vi] | v);
  dp[mask] = dp[without] + dp[withoutNb];
}

console.log(dp[total - 1] - 1);
